	@Test
	void mergedOverlayPageFragmentsMatchExactRunBindingsAndGraphRestrictedCounts() {
		long rootOne = ValueIds.createId(ValueIds.T_URI, 1L);
		long rootTwo = ValueIds.createId(ValueIds.T_URI, 2L);
		long dictionaryLiteral = ValueIds.createId(ValueIds.T_LITERAL, 41L);
		long inlineLiteral = ValueIds.createId(ValueIds.T_INTEGER, 7L);
		long unicodeDictionaryLiteral = ValueIds.createId(ValueIds.T_LITERAL, 42L);
		long namedGraph = ValueIds.createId(ValueIds.T_URI, 99L);

		// The page view is the visible merged snapshot: one base quad was deleted, and the overlay added the two
		// following quads. Splitting rootOne across pages models a continuation fragment at the page boundary.
		PageFixture mergedPages = new PageFixture(List.of(
				Page.accepted(rootOne, new long[] { dictionaryLiteral }, new long[] { namedGraph }),
				Page.accepted(rootOne, new long[] { inlineLiteral }, new long[] { 0L }),
				Page.accepted(rootTwo, new long[] { inlineLiteral, unicodeDictionaryLiteral },
						new long[] { namedGraph, namedGraph })));
		RunFixture mergedRuns = new RunFixture(List.of(
				new Run(rootOne, new long[] { dictionaryLiteral, inlineLiteral }, new long[] { namedGraph, 0L }),
				new Run(rootTwo, new long[] { inlineLiteral, unicodeDictionaryLiteral },
						new long[] { namedGraph, namedGraph })));

		assertFalse(ValueIds.isInlined(dictionaryLiteral));
		assertTrue(ValueIds.isInlined(inlineLiteral));
		assertEquals(ValueIds.TERM_KIND_LITERAL, ValueIds.termKind(dictionaryLiteral));
		assertEquals(ValueIds.TERM_KIND_LITERAL, ValueIds.termKind(inlineLiteral));

		List<PhysicalBinding> pageBindings;
		try (KernelAdjacencyCursor cursor = KernelAdjacencyCursor.open(mergedPages.adjacency())) {
			pageBindings = collectBindings(cursor);
		}
		List<PhysicalBinding> runBindings;
		try (KernelAdjacencyCursor cursor = KernelAdjacencyCursor.open(mergedRuns, null, null, null)) {
			runBindings = collectBindings(cursor);
		}

		assertEquals(runBindings, pageBindings,
				"page continuation fragments and the exact merged run cursor must expose the same bindings");
		assertEquals(4, pageBindings.size(), "each visible quad contributes one aggregate count");
		assertEquals(2, countRoot(pageBindings, rootOne));
		assertEquals(2, countRoot(pageBindings, rootTwo));
		assertEquals(1, countContext(pageBindings, 0L), "GRAPH ?g excludes the default graph when requested");
		assertEquals(3, countNamedContexts(pageBindings), "named graph restriction retains every named context");
		assertEquals(0, mergedPages.rejectedPayloadReads);
	}

