	@Test
	void pageCursorContinuesAcrossLargeFiberAndContextBatches() {
		long[] manyFibers = new long[300];
		long[] fiberContexts = new long[manyFibers.length];
		for (int i = 0; i < manyFibers.length; i++) {
			manyFibers[i] = 1_000L + i;
			fiberContexts[i] = 2_000L + i;
		}
		PageFixture fibers = new PageFixture(List.of(Page.accepted(7L, manyFibers, fiberContexts)));
		try (KernelAdjacencyCursor cursor = KernelAdjacencyCursor.open(fibers.adjacency())) {
			assertTrue(cursor.advanceRoot());
			int seen = 0;
			while (cursor.advanceFiber()) {
				assertEquals(manyFibers[seen], cursor.neighborId());
				assertEquals(1L, cursor.contextMultiplicity());
				assertTrue(cursor.advanceContext());
				assertEquals(fiberContexts[seen], cursor.contextId());
				assertFalse(cursor.advanceContext());
				seen++;
			}
			assertEquals(manyFibers.length, seen);
		}

		long[] repeatedNeighbor = new long[513];
		long[] manyContexts = new long[repeatedNeighbor.length];
		Arrays.fill(repeatedNeighbor, 77L);
		for (int i = 0; i < manyContexts.length; i++) {
			manyContexts[i] = i;
		}
		PageFixture contexts = new PageFixture(List.of(Page.accepted(8L, repeatedNeighbor, manyContexts)));
		try (KernelAdjacencyCursor cursor = KernelAdjacencyCursor.open(contexts.adjacency())) {
			assertTrue(cursor.advanceRoot());
			assertTrue(cursor.advanceFiber());
			assertEquals(513L, cursor.contextMultiplicity());
			for (int i = 0; i < manyContexts.length; i++) {
				assertTrue(cursor.advanceContext());
				assertEquals(manyContexts[i], cursor.contextId());
			}
			assertFalse(cursor.advanceContext());
			assertFalse(cursor.advanceFiber());
		}
	}

